const inputJson = $input.first().json;
let raw =
  inputJson.message?.content ||
  inputJson.choices?.[0]?.message?.content ||
  inputJson.text ||
  (typeof inputJson === 'string' ? inputJson : '') ||
  '';

raw = raw.trim();

// Extraer la URL de imagen del bucket de Supabase si viene en la respuesta
const urlMatch = raw.match(/https:\/\/hzgoxdpvlvzxzwoefeui\.supabase\.co\/storage[^\s\)\]"']+/);
const imagenUrl = urlMatch ? urlMatch[0] : null;

// Texto de respuesta sin la URL repetida
let respuesta = raw;
if (imagenUrl) {
  respuesta = raw.replace(imagenUrl, '').trim();
}

if (!respuesta) {
  respuesta = 'No encontre esa informacion en el manual del 360.';
}

return [{
  json: {
    output: imagenUrl ? (respuesta + '\n' + imagenUrl) : respuesta,
    url: imagenUrl,
    tiene_imagen: imagenUrl !== null
  }
}];
